func (m *Milvus) DeleteByMd5(ctx context.Context, md5 ...string) error {
	join := strings.Join(md5, ",")
	marshal, err := json.Marshal(join)
	if err != nil {
		return fmt.Errorf("json.Marshal失败: %w", err)
	}
	err = m.c.Delete(ctx, collName, "", fmt.Sprintf("md5 in %s", string(marshal)))
	if err != nil {
		return fmt.Errorf("删除失败: %w", err)
	}

	return nil
}

